    assert [i["text"] for i in todo.list_items(["--pending"])] == ["b"]


def test_list_done_flag_shows_only_done_items():
    todo.add("a")
    todo.add("b")
    todo.done(2)
    assert [i["text"] for i in todo.list_items(["--done"])] == ["b"]
